import{_ as n,C as i,o as e,c as l,a3 as r,b as o,w as s,a as d,E as c,a4 as p}from"./chunks/framework.BiZN3XWs.js";const v=JSON.parse('{"title":"Deterministic CBOR v1 (FRNK) Specification","description":"","frontmatter":{},"headers":[],"relativePath":"cbor/spec.md","filePath":"cbor/spec.md","lastUpdated":1791348521000}'),g={name:"cbor/spec.md"};function m(y,t,h,x,u,f){const a=i("Mermaid");return e(),l("div",null,[t[1]||(t[1]=r(`<h1 id="deterministic-cbor-v1-frnk-specification" tabindex="-1">Deterministic CBOR v1 (FRNK) Specification <a class="header-anchor" href="#deterministic-cbor-v1-frnk-specification" aria-label="Permalink to &quot;Deterministic CBOR v1 (FRNK) Specification&quot;">​</a></h1><p><strong>Status</strong>: Normative Encoding and Validation Standard<br><strong>Implementations</strong>: <code>@frank/codec</code> (TypeScript), <code>frank-cbor</code> (Rust zero-copy parser)<br><strong>Conformance Vectors</strong>: <code>docs/protocol/cbor/vectors/</code></p><hr><h2 id="_1-framing-architecture" tabindex="-1">1. Framing Architecture <a class="header-anchor" href="#_1-framing-architecture" aria-label="Permalink to &quot;1. Framing Architecture&quot;">​</a></h2><p>Every independently stored, signed, hashed, or forwarded Frank object is serialized as an exact binary <strong>frame</strong>:</p><table tabindex="0"><thead><tr><th style="text-align:center;">Offset</th><th style="text-align:center;">Size</th><th style="text-align:left;">Field</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:center;"><strong>0</strong></td><td style="text-align:center;">4 bytes</td><td style="text-align:left;">Magic Bytes</td><td style="text-align:left;">ASCII <code>FRNK</code> (<code>0x46 0x52 0x4e 0x4b</code>)</td></tr><tr><td style="text-align:center;"><strong>4</strong></td><td style="text-align:center;">1 byte</td><td style="text-align:left;">Frame Version</td><td style="text-align:left;">Protocol frame version (<code>0x01</code>)</td></tr><tr><td style="text-align:center;"><strong>5</strong></td><td style="text-align:center;">4 bytes</td><td style="text-align:left;">Body Length</td><td style="text-align:left;">Big-endian uint32 payload length (bytes <code>9..N</code>)</td></tr><tr><td style="text-align:center;"><strong>9</strong></td><td style="text-align:center;"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>N</mi></mrow><annotation encoding="application/x-tex">N</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">N</span></span></span></span> bytes</td><td style="text-align:left;">CBOR Envelope</td><td style="text-align:left;">Canonical CBOR map <code>{ 0: type_id, 1: schema_version, 2: min_reader_version, 3: payload_bytes }</code></td></tr></tbody></table><p>Worked example: a Type 17 text item <code>{0: &quot;hi&quot;}</code> (23 bytes total):</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>46 52 4e 4b            FRNK (magic)</span></span>
<span class="line"><span>01                     frame version 1</span></span>
<span class="line"><span>00 00 00 0e            CBOR body length 14</span></span>
<span class="line"><span>a4                     envelope map, 4 entries</span></span>
<span class="line"><span>  00 11                  0: type_id = 17 (text-message-item)</span></span>
<span class="line"><span>  01 01                  1: schema_version = 1</span></span>
<span class="line"><span>  02 01                  2: min_reader_version = 1</span></span>
<span class="line"><span>  03 45                  3: payload = 5-byte string</span></span>
<span class="line"><span>     a1 00 62 68 69        payload map {0: &quot;hi&quot;}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><hr><h2 id="_2-canonical-encoding-constraints-strict-cbor" tabindex="-1">2. Canonical Encoding Constraints (Strict CBOR) <a class="header-anchor" href="#_2-canonical-encoding-constraints-strict-cbor" aria-label="Permalink to &quot;2. Canonical Encoding Constraints (Strict CBOR)&quot;">​</a></h2><p>To ensure byte-for-byte deterministic hashing across all languages (TypeScript, Rust, Go, Python):</p><ol><li><strong>Integer Map Keys</strong>: All protocol map keys MUST be unsigned integers (<code>uint</code>), serialized in strictly ascending numerical order without duplicates. Text or string keys are forbidden.</li><li><strong>Minimal Integer Representation</strong>: Integers MUST use the shortest possible CBOR encoding (0–23 inline, 24–255 as 1-byte, 256–65535 as 2-byte, etc.).</li><li><strong>No Indefinite-Length Items</strong>: Indefinite-length byte strings, text strings, arrays, or maps are strictly rejected.</li><li><strong>No Floating-Point Values</strong>: IEEE 754 float types are disallowed in protocol records to prevent architecture-dependent precision loss.</li><li><strong>Exact UTF-8 String Encoding</strong>: Text strings MUST be valid UTF-8, with no unassigned Unicode code points or invalid surrogate pairs.</li><li><strong>Zero Trailing Bytes</strong>: The CBOR payload must consume exactly the remaining bytes of the frame. Trailing data is a fatal deserialization error.</li></ol><hr><h2 id="_3-type-id-allocation-registry" tabindex="-1">3. Type ID Allocation Registry <a class="header-anchor" href="#_3-type-id-allocation-registry" aria-label="Permalink to &quot;3. Type ID Allocation Registry&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;">Type ID</th><th style="text-align:center;">Hex</th><th style="text-align:left;">Name</th><th style="text-align:left;">CDDL Schema Rule</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:center;"><strong>1</strong></td><td style="text-align:center;"><code>0x0001</code></td><td style="text-align:left;">Direct Message Delivery</td><td style="text-align:left;"><code>direct-message-delivery</code></td><td style="text-align:left;">Outermost DKSAP message container with payment stamps</td></tr><tr><td style="text-align:center;"><strong>2</strong></td><td style="text-align:center;"><code>0x0002</code></td><td style="text-align:left;">Directory Attestation</td><td style="text-align:left;"><code>directory-attestation</code></td><td style="text-align:left;">Wraps and signs a Type 4 directory statement with ECDSA</td></tr><tr><td style="text-align:center;"><strong>3</strong></td><td style="text-align:center;"><code>0x0003</code></td><td style="text-align:left;">Mailbox Checkpoint</td><td style="text-align:left;"><code>mailbox-checkpoint</code></td><td style="text-align:left;">Durable journal facts and mailbox state checkpoint</td></tr><tr><td style="text-align:center;"><strong>4</strong></td><td style="text-align:center;"><code>0x0004</code></td><td style="text-align:left;">Directory Statement</td><td style="text-align:left;"><code>directory-statement</code></td><td style="text-align:left;">Account-to-relay binding, public keys (<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>P</mi><mo separator="true">,</mo><mi>M</mi><mo separator="true">,</mo><msup><mi>P</mi><mo mathvariant="normal" lspace="0em" rspace="0em">′</mo></msup></mrow><annotation encoding="application/x-tex">P, M, P&#39;</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9463em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">M</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.7519em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">′</span></span></span></span></span></span></span></span></span></span></span></span>), and revision</td></tr><tr><td style="text-align:center;"><strong>5</strong></td><td style="text-align:center;"><code>0x0005</code></td><td style="text-align:left;">Recipient Encrypted Payload</td><td style="text-align:left;"><code>recipient-encrypted-payload-v2</code></td><td style="text-align:left;">XChaCha20-Poly1305 ciphertext with DLEQ zero-knowledge proof</td></tr><tr><td style="text-align:center;"><strong>6</strong></td><td style="text-align:center;"><code>0x0006</code></td><td style="text-align:left;">Encrypted Message Content</td><td style="text-align:left;"><code>encrypted-message-content</code></td><td style="text-align:left;">Inner decrypted container with logical message ID &amp; payload</td></tr><tr><td style="text-align:center;"><strong>7</strong></td><td style="text-align:center;"><code>0x0007</code></td><td style="text-align:left;">Key Transition Statement</td><td style="text-align:left;"><code>key-transition-statement</code></td><td style="text-align:left;">Cryptographic authorization linking a retiring key to a new subject key</td></tr><tr><td style="text-align:center;"><strong>8</strong></td><td style="text-align:center;"><code>0x0008</code></td><td style="text-align:left;">Message Content Revision</td><td style="text-align:left;"><code>message-content-revision</code></td><td style="text-align:left;">Ordered array of semantic message items</td></tr><tr><td style="text-align:center;"><strong>9</strong></td><td style="text-align:center;"><code>0x0009</code></td><td style="text-align:left;">Topic Post Content</td><td style="text-align:left;"><code>topic-post</code></td><td style="text-align:left;">Public forum post content with structured authored entries</td></tr><tr><td style="text-align:center;"><strong>10</strong></td><td style="text-align:center;"><code>0x000a</code></td><td style="text-align:left;">Topic Post Submission</td><td style="text-align:left;"><code>topic-post-submission</code></td><td style="text-align:left;">Initial post creation paired with raw signed on-chain burn transaction (<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>T</mi><mn>7</mn></msub></mrow><annotation encoding="application/x-tex">T_7</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">7</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>)</td></tr><tr><td style="text-align:center;"><strong>11</strong></td><td style="text-align:center;"><code>0x000b</code></td><td style="text-align:left;">Topic Vote Submission</td><td style="text-align:left;"><code>topic-vote-submission</code></td><td style="text-align:left;">Upvote on existing post paired with raw signed on-chain burn transaction (<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>T</mi><mn>7</mn></msub></mrow><annotation encoding="application/x-tex">T_7</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">7</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>)</td></tr><tr><td style="text-align:center;"><strong>12</strong></td><td style="text-align:center;"><code>0x000c</code></td><td style="text-align:left;">Forum Post Observation</td><td style="text-align:left;"><code>forum-single-view</code></td><td style="text-align:left;">Single post observation paired with author address, raw signed burn tx, and vote weight</td></tr><tr><td style="text-align:center;"><strong>13</strong></td><td style="text-align:center;"><code>0x000d</code></td><td style="text-align:left;">Forum Topic Batch (<code>forum-topic-page</code>)</td><td style="text-align:left;"><code>forum-topic-page</code></td><td style="text-align:left;">Paginated batch of up to 128 post observation frames within a topic, with continuation cursor and relay epoch</td></tr><tr><td style="text-align:center;"><strong>14</strong></td><td style="text-align:center;"><code>0x000e</code></td><td style="text-align:left;">Forum Discovery Listing (<code>forum-discovery-page</code>)</td><td style="text-align:left;"><code>forum-discovery-page</code></td><td style="text-align:left;">Paginated directory of active topics, post counts, and last activity timestamps</td></tr><tr><td style="text-align:center;"><strong>15</strong></td><td style="text-align:center;"><code>0x000f</code></td><td style="text-align:left;">Forum Operation Status</td><td style="text-align:left;"><code>forum-operation-status</code></td><td style="text-align:left;">Relay submission/confirmation status report for an on-chain burn transaction</td></tr><tr><td style="text-align:center;"><strong>16</strong></td><td style="text-align:center;"><code>0x0010</code></td><td style="text-align:left;">Container Message Item</td><td style="text-align:left;"><code>container-message-item</code></td><td style="text-align:left;">Opaque nested child frame container for multi-item deliveries</td></tr><tr><td style="text-align:center;"><strong>17</strong></td><td style="text-align:center;"><code>0x0011</code></td><td style="text-align:left;">UTF-8 Text Item</td><td style="text-align:left;"><code>text-message-item</code></td><td style="text-align:left;">Plaintext chat message text up to 256 KiB</td></tr><tr><td style="text-align:center;"><strong>19</strong></td><td style="text-align:center;"><code>0x0013</code></td><td style="text-align:left;">Stealth Payment Item</td><td style="text-align:left;"><code>stealth-message-item</code></td><td style="text-align:left;">Single-use ephemeral DKSAP on-chain transfer notification</td></tr><tr><td style="text-align:center;"><strong>24</strong></td><td style="text-align:center;"><code>0x0018</code></td><td style="text-align:left;">Universal State Channel Update</td><td style="text-align:left;"><code>channel-update-item</code></td><td style="text-align:left;">Instant off-chain multi-network state execution and interactive turns</td></tr><tr><td style="text-align:center;"><strong>25</strong></td><td style="text-align:center;"><code>0x0019</code></td><td style="text-align:left;">Forwarding Delivery Envelope</td><td style="text-align:left;"><code>forwarding-delivery-envelope</code></td><td style="text-align:left;">Store-and-forward relay hop delivery envelope with storage stamps (up to 32 MiB)</td></tr></tbody></table><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p><strong>Database Pagination vs. Web Pages</strong>: In Types 13 and 14 (<code>forum-topic-page</code> and <code>forum-discovery-page</code>), the term <strong>&quot;Page&quot;</strong> refers strictly to cursor-based database query result sets (holding up to 128 verified post observations with continuation cursors), not HTML documents or rendered web pages.</p></div><hr><h2 id="_4-multi-stage-validation-order" tabindex="-1">4. Multi-Stage Validation Order <a class="header-anchor" href="#_4-multi-stage-validation-order" aria-label="Permalink to &quot;4. Multi-Stage Validation Order&quot;">​</a></h2><p>Implementations MUST process frames through twelve rigorous validation stages:</p>`,19)),(e(),o(p,null,{default:s(()=>[c(a,{id:"mermaid-511",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20S1%5B%221.%20Frame%20Boundary%20%26%20Magic%20('FRNK')%22%5D%20--%3E%20S2%5B%222.%20Version%20%26%20Length%20Validation%22%5D%0A%20%20%20%20S2%20--%3E%20S3%5B%223.%20Digest%20Verification%20(T1%20%2F%20T2%20%2F%20T3)%22%5D%0A%20%20%20%20S3%20--%3E%20S4%5B%224.%20Resource%20Bounds%20Check%20(Heap%2FDepth%2FItem%20Limits)%22%5D%0A%20%20%20%20S4%20--%3E%20S5%5B%225.%20Canonical%20CBOR%20Syntax%20Verification%22%5D%0A%20%20%20%20S5%20--%3E%20S6%5B%226.%20Minimum%20Reader%20Version%20Gate%22%5D%0A%20%20%20%20S6%20--%3E%20S7%5B%227.%20Schema%20Structural%20Validation%20(CDDL%20matching)%22%5D%0A%20%20%20%20S7%20--%3E%20S8%5B%228.%20Semantic%20Predicate%20Validation%22%5D%0A%20%20%20%20S8%20--%3E%20S9%5B%229.%20Cryptographic%20Curve%20Point%20Validation%20(secp256k1)%22%5D%0A%20%20%20%20S9%20--%3E%20S10%5B%2210.%20Zero-Knowledge%20Proofs%20(DLEQ)%22%5D%0A%20%20%20%20S10%20--%3E%20S11%5B%2211.%20Digital%20Signature%20Verification%20(strict-DER%20low-S%20ECDSA)%22%5D%0A%20%20%20%20S11%20--%3E%20S12%5B%2212.%20State%20Machine%20Admission%20%26%20State%20Commit%22%5D%0A"})]),fallback:s(()=>[...t[0]||(t[0]=[d(" Loading... ",-1)])]),_:1}))])}const S=n(g,[["render",m]]);export{v as __pageData,S as default};
